                _cashOutShown = offer;
                _cashOutRoundShown = RoundBucket(offer);
                RenderCashOut(offer);
                return;
            }

            if (Math.Abs(offer - _cashOutShown) < 0.005)
            {
                RenderCashOut(_cashOutShown);
                return;
            }

            bool dropped = offer < _cashOutShown;
            if (dropped) _cashOutFlash = 1f; // gold taunt, never a money-bad red signal
            StopCashOutAnimation();
            _cashOutAnimation = StartCoroutine(AnimateCashOut(_cashOutShown, offer));
        }

        private IEnumerator AnimateCashOut(double from, double to)
        {
            float duration = Mathf.Max(0f, cashOutTickDuration * Mathf.Max(0f, TimeScaleOverride));
            if (duration <= 0f)
            {
                _cashOutShown = to;
                RenderCashOut(to);
                _cashOutAnimation = null;
                yield break;
            }

            float elapsed = 0f;
            while (elapsed < duration)
            {
                elapsed += Time.deltaTime;
                float t = Mathf.Clamp01(elapsed / duration);
                _cashOutShown = from + (to - from) * t;
                int bucket = RoundBucket(_cashOutShown);
                if (bucket != _cashOutRoundShown)
                {
                    _cashOutRoundShown = bucket;
                    _cashOutScale = 1.18f;
                }
                RenderCashOut(_cashOutShown);
                yield return null;
            }

            _cashOutShown = to;
            _cashOutRoundShown = RoundBucket(to);
            RenderCashOut(to);
            _cashOutAnimation = null;
        }

        private int RoundBucket(double amount)
        {
            double multiple = Math.Max(1.0, cashOutRoundMultiple);
            return (int)Math.Floor(amount / multiple);
        }

        private void RenderCashOut(double amount)
        {
            if (_tCashOut == null) return;
            _tCashOut.text = $"CASH OUT ${Money(amount)}   [E]";
        }

        private void StopCashOutAnimation()
        {
            if (_cashOutAnimation != null)
            {
                StopCoroutine(_cashOutAnimation);
                _cashOutAnimation = null;
            }
        }

        private string MatchupLine(Leg leg)
        {
            string away = SweatFlavor.Short(leg.Matchup.Away.Name);
            string home = SweatFlavor.Short(leg.Matchup.Home.Name);
            // Mark the picked side with a dot so the player knows which team is theirs.
            string awayMark = leg.Side == Side.Away ? "● " : "";
            string homeMark = leg.Side == Side.Home ? " ●" : "";
            return $"{awayMark}{away.ToUpperInvariant()}  @  {home.ToUpperInvariant()}{homeMark}";
        }

        private static string RecordsLine(Leg leg)
            => $"({leg.Matchup.Away.Record})          ({leg.Matchup.Home.Record})"; // season W-L

        // ---------------------------------------------------------------- beats

        private IEnumerator ResolveBeat(DramaEvent evt)
        {
            Leg leg = _ticket.Legs[evt.LegIndex];
            int k = evt.LegIndex + 1;

            if (leg.IsVoided)
            {
                _tFlavor.color = chromeCyan;
                _tFlavor.text = $"LEG {k} - VOIDED, the ticket lives";
                yield return ScaledWait(deadLineDuration);
            }
            else if (leg.GradesWon)
            {
                yield return GreenLegBeat(k);
            }
            else
            {
                yield return DeadLegBeat(k);
            }

            _resolvedThrough = evt.LegIndex + 1;
            UpdateSlipStrip(evt.LegIndex + 1); // next leg reads LIVE once its events start
        }

        private IEnumerator GreenLegBeat(int k)
        {
            _tFlavor.color = new Color(phosphorGreen.r, phosphorGreen.g, phosphorGreen.b, 1f);
            _tFlavor.text = $"LEG {k} - GREEN";
            EmissionFlash(phosphorGreen * 1.0f);
            tvLight?.Flash(new Color(0.30f, 1f, 0.45f), 3.0f);
            yield return FloodPulse(_greenFlood, new Color(0.15f, 1f, 0.35f), 0.55f, greenFloodDuration);
        }

        private IEnumerator DeadLegBeat(int k)
        {
            // 1) static - regenerate the noise a few times so it crawls.
            SetRawAlpha(_staticNoise, 0.85f);
            tvLight?.Flash(new Color(1f, 0.2f, 0.15f), 2.2f);
            float dur = Mathf.Max(0f, deadStaticDuration * Mathf.Max(0f, TimeScaleOverride));
            int regens = Mathf.Max(1, staticRegens);
            float per = dur / regens;
            for (int i = 0; i < regens; i++)
            {
                RegenNoise();
                yield return WaitRealtime(per);
            }
            SetRawAlpha(_staticNoise, 0f);

            // 2) the red DEAD line + the screen dropping darker.
            _tFlavor.color = new Color(hotRed.r, hotRed.g, hotRed.b, 1f);
            _tFlavor.text = $"LEG {k} - DEAD";
            _emissRest = new Color(_emissIdle.r * 0.3f, _emissIdle.g * 0.12f, _emissIdle.b * 0.12f); // darker, redder
            EmissionFlash(new Color(0.25f, 0.02f, 0.02f));
            tvLight?.SetRest(new Color(0.7f, 0.18f, 0.15f), 0.32f);
            yield return ScaledWait(deadLineDuration);
        }

        private IEnumerator TicketDeadBeat()
        {
            // TV dims to near-black for a beat before the next demo ticket.
            tvLight?.SetRest(new Color(0.5f, 0.12f, 0.1f), 0.18f);
            float dur = Mathf.Max(0f, ticketDeadDimDuration * Mathf.Max(0f, TimeScaleOverride));
            float t = 0f;
            while (t < dur)
            {
                t += Time.deltaTime;
                SetAlpha(_dimOverlay, Mathf.Lerp(0f, 0.94f, t / dur));
                yield return null;
            }
            SetAlpha(_dimOverlay, 0.94f);
            yield return ScaledWait(ticketDeadSilenceDuration);

            string[] consolation =
            {
                "the book thanks you for your patronage.",
                "so close. they always are.",
                "a courtesy: nobody saw that.",
                "the model remains extremely confident."
            };
            int ticketIndex = director != null ? director.SweatIndex : 0;
            _tFlavor.color = flavorColor;
            _tFlavor.text = consolation[Math.Abs(ticketIndex) % consolation.Length];
            _flavorScale = 1.05f;
            yield return ScaledWait(ticketDeadConsolationDuration);
        }

        private IEnumerator WinBeat()
        {
            double payout = _ticket.PotentialPayout;
            _tBigAmount.color = new Color(gold.r, gold.g, gold.b, 1f);
            _tBigAmount.text = "+$0";
            EmissionFlash(gold);
            tvLight?.Flash(new Color(1f, 0.82f, 0.25f), 3.4f);
            StartCoroutine(FloodPulse(_goldFlood, new Color(1f, 0.78f, 0.15f), 0.5f, winFloodDuration));
            StartCoroutine(WinConfetti());

            float duration = Mathf.Max(0f, winTallyDuration * Mathf.Max(0f, TimeScaleOverride));
            float elapsed = 0f;
            while (elapsed < duration)
            {
                elapsed += Time.deltaTime;
                float t = duration <= 0f ? 1f : Mathf.Clamp01(elapsed / duration);
                _tBigAmount.text = $"+${Money(payout * t)}";
                yield return null;
            }
            _tBigAmount.text = $"+${Money(payout)}";
            yield return ScaledWait(Mathf.Max(0f, winConfettiDuration - winTallyDuration));
            _tBigAmount.text = string.Empty;
        }

        private IEnumerator WinConfetti()
        {
            CleanupConfetti();
            int count = Mathf.Max(0, winConfettiCount);
            for (int i = 0; i < count; i++)
            {
                var go = new GameObject($"WinConfetti_{i}", typeof(Image));
                go.transform.SetParent(_canvasRoot, false);
                var image = go.GetComponent<Image>();
                image.raycastTarget = false;
                image.color = _confettiRandom.NextDouble() < 0.68
                    ? new Color(gold.r, gold.g, gold.b, 1f)
                    : Color.white;
                var rt = image.rectTransform;
                rt.anchorMin = rt.anchorMax = new Vector2(0.5f, 0.5f);
                rt.pivot = new Vector2(0.5f, 0.5f);
                float side = 8f + (float)_confettiRandom.NextDouble() * 6f;
                rt.sizeDelta = new Vector2(side, side);
                rt.anchoredPosition = new Vector2(
                    (float)(_confettiRandom.NextDouble() * _canvasWidth - _canvasWidth * 0.5),
                    _canvasHeight * 0.5f + 8f + (float)_confettiRandom.NextDouble() * 32f);
                _confetti.Add(new ConfettiPiece
                {
                    Rect = rt,
                    Velocity = new Vector2((float)(_confettiRandom.NextDouble() * 70f - 35f),
                        -(70f + (float)_confettiRandom.NextDouble() * 80f)),
                    Spin = (float)(_confettiRandom.NextDouble() * 360f - 180f)
                });
            }

            float duration = Mathf.Max(0f, winConfettiDuration * Mathf.Max(0f, TimeScaleOverride));
            float elapsed = 0f;
            while (elapsed < duration)
            {
                elapsed += Time.deltaTime;
                float storyDt = Time.deltaTime / Mathf.Max(0.0001f, TimeScaleOverride);
                for (int i = 0; i < _confetti.Count; i++)
                {
                    ConfettiPiece piece = _confetti[i];
                    if (piece.Rect == null) continue;
                    piece.Velocity.y -= 150f * storyDt;
                    piece.Rect.anchoredPosition += piece.Velocity * storyDt;
                    piece.Rect.Rotate(0f, 0f, piece.Spin * storyDt);
                    _confetti[i] = piece;
                }
                yield return null;
            }
            CleanupConfetti();
        }

        private void CleanupConfetti()
        {
            for (int i = 0; i < _confetti.Count; i++)
                if (_confetti[i].Rect != null) Destroy(_confetti[i].Rect.gameObject);
            _confetti.Clear();
        }

        /// <summary>Fired from Update the instant E is accepted, so the gold hit is responsive.</summary>
        private IEnumerator CashOutFloodBeat(double amount)
        {
            _tBigAmount.color = new Color(gold.r, gold.g, gold.b, 1f);
            _tBigAmount.text = $"${Money(amount)}";
            _tCashOut.enabled = false;
            EmissionFlash(gold);
            tvLight?.Flash(new Color(1f, 0.82f, 0.25f), 3.4f);
            yield return FloodPulse(_goldFlood, new Color(1f, 0.78f, 0.15f), 0.55f, cashOutFloodDuration);
            _tBigAmount.text = string.Empty;
        }

        private IEnumerator FloodPulse(Image flood, Color color, float peakAlpha, float baseDuration)
        {
            flood.color = new Color(color.r, color.g, color.b, 0f);
            float dur = Mathf.Max(0f, baseDuration * Mathf.Max(0f, TimeScaleOverride));
            float t = 0f;
            while (t < dur)
            {
                t += Time.deltaTime;
                float a = Mathf.Sin(Mathf.Clamp01(t / dur) * Mathf.PI) * peakAlpha; // rise then settle
                SetAlpha(flood, a);
                yield return null;
            }
            SetAlpha(flood, 0f);
        }

using System.Collections.Generic;
using SBR.Engine;
using UnityEngine;
using UnityEngine.UI;

namespace SBR.Game
{
    /// <summary>
    /// The sweat's memory aid: one compact strip per leg. Dots are only added by the TV's
    /// reveal callbacks, so looking away never spoils a beat. Resolved rows collapse to a
    /// money-signal cap; team-colored dots themselves never use reserved money colors.
    /// </summary>
    public sealed class MomentumTape : MonoBehaviour
    {
        private const float SmallDot = 6f;
        private const float MidDot = 9f;
        private const float BigDot = 12f;
        private const float RowHeight = 14f;
        private const float RowGap = 3f;

        private readonly List<Row> _rows = new List<Row>();
        private RectTransform _rect;
        private float _rowWidth;
        private Color _green = new Color(0x3C / 255f, 0xE8 / 255f, 0x73 / 255f, 1f);
        private Color _red = new Color(0xFF / 255f, 0x40 / 255f, 0x38 / 255f, 1f);
        private Color _cyan = new Color(0x9E / 255f, 0xDC / 255f, 0xF6 / 255f, 1f);

        private sealed class Row
        {
            public readonly RectTransform Root;
            public readonly Image Cap;
            public readonly List<Image> Dots = new List<Image>();
            public float Cursor;

            public Row(RectTransform root, Image cap)
            {
                Root = root;
                Cap = cap;
            }
        }

        /// <summary>Builds a code-only UGUI tape in the supplied canvas hierarchy.</summary>
        public static MomentumTape Build(Transform parent, Vector2 position, Vector2 size)
        {
            var go = new GameObject("MomentumTape", typeof(RectTransform), typeof(MomentumTape));
            go.transform.SetParent(parent, false);
            var tape = go.GetComponent<MomentumTape>();
            tape._rect = go.GetComponent<RectTransform>();
            tape._rect.anchorMin = tape._rect.anchorMax = new Vector2(0.5f, 0.5f);
            tape._rect.pivot = new Vector2(0.5f, 0.5f);
            tape._rect.sizeDelta = size;
            tape._rect.anchoredPosition = position;
            tape._rowWidth = Mathf.Max(1f, size.x);
            tape.Show(false);
            return tape;
        }

        /// <summary>Rebuilds the compact rows for a new ticket.</summary>
        public void ResetForTicket(int legCount)
        {
            for (int i = 0; i < _rows.Count; i++)
                Destroy(_rows[i].Root.gameObject);
            _rows.Clear();

            int count = Mathf.Max(0, legCount);
            float totalHeight = count * RowHeight + Mathf.Max(0, count - 1) * RowGap;
            for (int i = 0; i < count; i++)
            {
                var rowGo = new GameObject($"LegTape_{i + 1}", typeof(RectTransform));
                rowGo.transform.SetParent(transform, false);
                var rowRt = rowGo.GetComponent<RectTransform>();
                rowRt.anchorMin = rowRt.anchorMax = new Vector2(0f, 0.5f);
                rowRt.pivot = new Vector2(0f, 0.5f);
                rowRt.sizeDelta = new Vector2(_rowWidth, RowHeight);
                rowRt.anchoredPosition = new Vector2(-_rowWidth * 0.5f,
                    totalHeight * 0.5f - RowHeight * 0.5f - i * (RowHeight + RowGap));

                var capGo = new GameObject("ResolutionCap", typeof(Image));
                capGo.transform.SetParent(rowGo.transform, false);
                var cap = capGo.GetComponent<Image>();
                cap.raycastTarget = false;
                cap.enabled = false;
                var capRt = cap.rectTransform;
                capRt.anchorMin = capRt.anchorMax = new Vector2(0f, 0.5f);
                capRt.pivot = new Vector2(0f, 0.5f);
                capRt.anchoredPosition = Vector2.zero;
                capRt.sizeDelta = new Vector2(_rowWidth, 4f);

                _rows.Add(new Row(rowRt, cap));
            }
        }

        /// <summary>Appends one revealed non-final beat to a leg's live strip.</summary>
        public void AppendBeat(int legIx, Color beneficiary, int band)
        {
            if (legIx < 0 || legIx >= _rows.Count) return;
            Row row = _rows[legIx];
            if (row.Cap.enabled) return;

            float diameter = band <= 0 ? SmallDot : band == 1 ? MidDot : BigDot;
            var dotGo = new GameObject($"Beat_{row.Dots.Count + 1}", typeof(Image));
            dotGo.transform.SetParent(row.Root, false);
            var dot = dotGo.GetComponent<Image>();
            dot.color = beneficiary;
            dot.raycastTarget = false;
            var dotRt = dot.rectTransform;
            dotRt.anchorMin = dotRt.anchorMax = new Vector2(0f, 0.5f);
            dotRt.pivot = new Vector2(0f, 0.5f);
            dotRt.sizeDelta = new Vector2(diameter, diameter);
            dotRt.anchoredPosition = new Vector2(row.Cursor, 0f);
            row.Cursor += diameter + 3f;
            row.Dots.Add(dot);
        }

        /// <summary>Collapses a resolved leg to its sanctioned money-signal cap.</summary>
        public void ResolveLeg(int legIx, LegGrade grade)
        {
            if (legIx < 0 || legIx >= _rows.Count) return;
            Row row = _rows[legIx];
            for (int i = 0; i < row.Dots.Count; i++) row.Dots[i].enabled = false;

            row.Cap.color = grade == LegGrade.Won ? _green
                : grade == LegGrade.Lost ? _red : _cyan;
            row.Cap.enabled = true;
        }

        public void Show(bool visible)
        {
            if (gameObject.activeSelf != visible) gameObject.SetActive(visible);
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using NUnit.Framework;
using SBR.Engine;
using SBR.Game;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;

namespace SBR.Tests.PlayMode
{
    /// <summary>
    /// M4 PlayMode: the real round loop through the room's surfaces. Tickets are placed through the
    /// engine (DemoTicketPolicy is the auto-play fixture — the laptop UI is a thin renderer over the
    /// EditMode-tested BetslipModel), the director locks, the TV walks the sweats serially while
    /// seated, the round settles and the shop opens. Also: standing mid-sweat freezes the cursor
    /// (design/04), and a zero-ticket lock settles on the spot.
    /// All waits are wall-clock — batch mode runs unthrottled (M3's lesson).
    /// Requires the scene in EditorBuildSettings - run SBR.GrayboxRoomBuilder.Build first.
    /// </summary>
    public class TvSweatScreenTests
    {
        [UnityTest]
        public IEnumerator FullRound_TwoTickets_SweatsSeriallyToSettleAndShop()
        {
            yield return LoadRoom();

            var director = UnityEngine.Object.FindAnyObjectByType<RunDirector>();
            var screen = UnityEngine.Object.FindAnyObjectByType<TvSweatScreen>();
            var couch = UnityEngine.Object.FindAnyObjectByType<SitSpot>();
            Assert.IsNotNull(director, "RunDirector missing");
            Assert.IsNotNull(screen, "TvSweatScreen missing");
            Assert.IsNotNull(couch, "SitSpot missing");

            screen.TimeScaleOverride = 0.0001f; // fast-forward pacing, beats and cards
            couch.transitionDuration = 0.01f;

            yield return WaitUntil(() => director.Run != null, 10f, "director never started a run");
            Run run = director.Run;
            Assert.AreEqual(Phase.Betting, run.Phase, "a fresh run opens in Betting");

            // Ticket 1 via the auto-play fixture; ticket 2 a single-leg bet on an unused matchup.
            (IReadOnlyList<Pick> picks, double stake) = DemoTicketPolicy.Choose(run);
            run.PlaceTicket(picks, stake);
            run.PlaceTicket(new List<Pick> { new Pick(UnusedMatchup(run, picks), Side.Home) }, 10);

            director.LockRound();
            Assert.AreEqual(Phase.Sweat, run.Phase);
            Assert.AreEqual(2, run.Sweats.Count, "one session per ticket");

            couch.OnInteract(null);
            yield return WaitUntil(() => SitSpot.Active != null, 10f, "player never sat down");

            yield return WaitUntil(
                () => run.Phase == Phase.Shop || run.Phase == Phase.RunWon || run.Phase == Phase.RunLost,
                60f, "the round never settled");

            Assert.IsTrue(director.LastSettle.HasValue, "settle card telemetry missing");
            foreach (Ticket t in run.Tickets)
                Assert.AreNotEqual(TicketState.Open, t.State, "every ticket must reach a terminal state");
            Assert.Greater(run.Bank, 0.0, "bank went non-positive");

            if (run.Phase == Phase.Shop)
            {
                int round = run.Round;
                director.ExitShop();
                Assert.AreEqual(Phase.Betting, run.Phase, "leaving the shop opens the next round");
                Assert.AreEqual(round + 1, run.Round);
                Assert.AreEqual(0, run.Tickets.Count, "the new round starts with a clean slate");
            }
        }

        [UnityTest]
        public IEnumerator StandingMidSweatFreezesTheEventCursor()
        {
            yield return LoadRoom();

            var director = UnityEngine.Object.FindAnyObjectByType<RunDirector>();
            var screen = UnityEngine.Object.FindAnyObjectByType<TvSweatScreen>();
            var couch = UnityEngine.Object.FindAnyObjectByType<SitSpot>();
            Assert.IsNotNull(director);
            Assert.IsNotNull(screen);
            Assert.IsNotNull(couch);

            // Moderate pacing so events land ~70-180ms apart in real time - a broken pause would
            // measurably advance the cursor inside the freeze windows below at any frame rate.
            screen.TimeScaleOverride = 0.15f;
            couch.transitionDuration = 0.01f;

            yield return WaitUntil(() => director.Run != null, 10f, "director never started a run");
            Run run = director.Run;

            (IReadOnlyList<Pick> picks, double stake) = DemoTicketPolicy.Choose(run);
            run.PlaceTicket(picks, stake);
            director.LockRound();

            // Before sitting, the sweat must not advance at all (card and steps gate on seated).
            yield return WaitRealtime(0.3f);
            Assert.AreEqual(0, screen.EventsEmitted, "sweat advanced before the player sat down");

            couch.OnInteract(null);
            yield return WaitUntil(() => SitSpot.Active != null, 10f, "player never sat down");

            yield return WaitUntil(() => screen.EventsEmitted >= 2 && !screen.SweatComplete, 20f,
                "sweat never made mid-run progress");

            // Look away / stand: the cursor must freeze.
            screen.ForceSeated(false);
            yield return WaitRealtime(0.3f); // absorb at most one in-flight step
            int frozenAt = screen.EventsEmitted;
            Assert.IsFalse(screen.SweatComplete, "sweat should still be mid-run when we stand");

            yield return WaitRealtime(0.6f); // several event-lengths of real time
            Assert.AreEqual(frozenAt, screen.EventsEmitted, "event cursor advanced while standing");
            Assert.IsFalse(screen.SweatComplete, "sweat should stay paused while standing");
        }

        [UnityTest]
        public IEnumerator ZeroTicketLockSettlesOnTheSpot()
        {
            yield return LoadRoom();

            var director = UnityEngine.Object.FindAnyObjectByType<RunDirector>();
            Assert.IsNotNull(director);
            yield return WaitUntil(() => director.Run != null, 10f, "director never started a run");

            director.LockRound(); // no tickets: the director settles without TV ceremony

            // Starting bank 350 >= round-1 payment 60, so a no-bet round always pays into the shop.
            Assert.AreEqual(Phase.Shop, director.Run.Phase, "no-bet round should settle straight to Shop");
            Assert.IsTrue(director.LastSettle.HasValue);
            Assert.IsTrue(director.LastSettle.Value.Paid);
        }

        // ---- helpers ----

        private static int UnusedMatchup(Run run, IReadOnlyList<Pick> used)
        {
            for (int i = 0; i < run.CurrentSlate.Matchups.Count; i++)
            {
                bool taken = false;
                foreach (Pick p in used)
                    if (p.MatchupIndex == i) { taken = true; break; }
                if (!taken) return i;
            }
            throw new InvalidOperationException("no unused matchup on the slate");
        }

        private static IEnumerator LoadRoom()
        {
            AsyncOperation load = SceneManager.LoadSceneAsync("Room", LoadSceneMode.Single);
            Assert.IsNotNull(load, "Room scene not in build settings - run SBR.GrayboxRoomBuilder.Build first.");
            while (!load.isDone) yield return null;
        }

        // Waits are wall-clock, not frame-count: batch mode runs unthrottled (thousands of fps),
        // so frame budgets starve anything driven by Time.deltaTime (e.g. the couch camera lerp).
        private static IEnumerator WaitUntil(Func<bool> cond, float maxSeconds, string failMessage)
        {
            float start = Time.realtimeSinceStartup;
            while (!cond())
            {
                if (Time.realtimeSinceStartup - start > maxSeconds)
                {
                    Assert.Fail($"{failMessage} (waited {maxSeconds}s)");
                    yield break;
                }
                yield return null;
            }
        }

        private static IEnumerator WaitRealtime(float seconds)
        {
            float start = Time.realtimeSinceStartup;
            while (Time.realtimeSinceStartup - start < seconds) yield return null;
        }
    }
